def reglages_initiaux(apps, schema_editor):
    """Ce qui valait avant reste vrai.

    - « Les Jëfs du Kourel » ne sonnait jamais : `push_enabled` à faux.
    - Les cartes déjà publiées d'un donateur qui a accepté d'être nommé
      reçoivent leur montant, pour que l'interrupteur des montants vaille
      aussi pour l'historique. Une carte anonyme n'en reçoit jamais.
    """
    Chat = apps.get_model('comms', 'Chat')
    Message = apps.get_model('comms', 'Message')
    Donation = apps.get_model('contributions', 'Donation')
    Chat.objects.filter(channel_kind='jefs').update(push_enabled=False)
    for message in Message.objects.filter(message_type='card').iterator():
        payload = dict(message.payload or {})
        if not payload.get('donor') or not payload.get('donation_id') or 'amount' in payload:
            continue
        montant = Donation.objects.filter(pk=payload['donation_id']).values_list('amount', flat=True).first()
        if montant is None:
            continue
        payload['amount'] = int(montant)
        Message.objects.filter(pk=message.pk).update(payload=payload)


